css:
.masic-page{background:#f4f0e7;color:#282622;font-family:var(--font-manrope),Arial,sans-serif;overflow:hidden}
.masic-shell{width:min(1320px,calc(100% - 40px));margin:0 auto}
.masic-kicker{margin:0 0 22px;text-transform:uppercase;letter-spacing:.22em;font-size:12px;font-weight:700}
.masic-title{margin:0;font-size:clamp(42px,6.4vw,96px);line-height:.96;letter-spacing:-.055em;font-weight:750}
.masic-title em{display:block;font-style:normal;font-weight:350;color:rgba(255,255,255,.78)}
.masic-lead{max-width:620px;margin:28px 0 0;font-size:clamp(17px,1.7vw,22px);line-height:1.65}
.masic-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:34px}
.masic-btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 24px;border:1px solid transparent;background:#9a4937;color:#fff;text-decoration:none;text-transform:uppercase;letter-spacing:.13em;font-size:12px;font-weight:800;transition:.25s ease}
.masic-btn:hover{transform:translateY(-2px);background:#7f382a}
.masic-btn--light{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.48);backdrop-filter:blur(10px)}
.masic-btn--dark{background:#282622}
.masic-hero{position:relative;min-height:92svh;display:flex;align-items:flex-end;background:#282622;color:#fff}
.masic-hero__image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 58%}
.masic-hero__shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(23,21,19,.88) 0%,rgba(23,21,19,.48) 56%,rgba(23,21,19,.2) 100%),linear-gradient(0deg,rgba(23,21,19,.8),transparent 55%)}
.masic-hero__content{position:relative;z-index:1;padding-top:170px;padding-bottom:62px}
.masic-hero__meta{display:flex;justify-content:space-between;gap:24px;margin-top:60px;padding-top:22px;border-top:1px solid rgba(255,255,255,.28);font-size:13px;color:rgba(255,255,255,.75)}
.masic-section{padding:clamp(76px,10vw,144px) 0}
.masic-section--dark{background:#282622;color:#f4f0e7}
.masic-section--wine{background:#743728;color:#fff}
.masic-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:clamp(18px,3vw,42px);align-items:center}
.masic-copy{grid-column:1/span 5}
.masic-media{grid-column:7/span 6}
.masic-section h2{margin:0;font-size:clamp(38px,5vw,72px);line-height:1.02;letter-spacing:-.045em}
.masic-section h3{margin:0;font-size:clamp(24px,2.6vw,38px);line-height:1.08;letter-spacing:-.035em}
.masic-body{margin-top:26px;font-size:17px;line-height:1.8;color:rgba(40,38,34,.75)}
.masic-section--dark .masic-body,.masic-section--wine .masic-body{color:rgba(255,255,255,.74)}
.masic-photo{display:block;width:100%;height:auto;object-fit:cover}
.masic-photo--portrait{aspect-ratio:4/5}
.masic-photo--landscape{aspect-ratio:4/3}
.masic-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-top:38px;background:rgba(40,38,34,.18)}
.masic-fact{padding:22px;background:#f4f0e7}
.masic-fact strong{display:block;font-size:24px}
.masic-fact span{display:block;margin-top:5px;font-size:12px;color:rgba(40,38,34,.65)}
.masic-heading{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:42px}
.masic-heading p{max-width:500px;margin:0;line-height:1.7;color:rgba(40,38,34,.67)}
.masic-section--dark .masic-heading p{color:rgba(255,255,255,.68)}
.masic-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.masic-card{position:relative;min-height:500px;overflow:hidden;background:#3c3934;color:#fff}
.masic-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .7s ease}
.masic-card:hover img{transform:scale(1.035)}
.masic-card::after{content:"";position:absolute;inset:30% 0 0;background:linear-gradient(transparent,rgba(20,18,16,.9))}
.masic-card__copy{position:absolute;z-index:1;left:26px;right:26px;bottom:26px}
.masic-card__copy p{margin:8px 0 0;color:rgba(255,255,255,.72)}
.masic-menu{display:grid;grid-template-columns:1fr 1fr;gap:0 50px;margin-top:34px}
.masic-menu__item{display:grid;grid-template-columns:1fr auto;gap:12px;padding:20px 0;border-bottom:1px solid rgba(255,255,255,.18)}
.masic-menu__item strong{font-size:17px}
.masic-menu__item span{display:block;color:rgba(255,255,255,.64);font-size:14px;margin-top:5px}
.masic-menu__item b{font-size:16px}
.masic-gallery{display:grid;grid-template-columns:1.2fr .8fr .8fr;gap:16px}
.masic-gallery img{width:100%;height:560px;object-fit:cover}
.masic-gallery img:nth-child(2),.masic-gallery img:nth-child(3){height:470px;margin-top:90px}
.masic-contact{display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(34px,8vw,110px);align-items:start}
.masic-details{display:grid;gap:24px;margin-top:34px}
.masic-detail{padding-top:18px;border-top:1px solid rgba(255,255,255,.25)}
.masic-detail span{display:block;text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:rgba(255,255,255,.58)}
.masic-detail strong,.masic-detail a{display:block;margin-top:8px;color:#fff;text-decoration:none;font-size:20px}
.masic-promo{padding:clamp(30px,5vw,58px);background:#f4f0e7;color:#282622}
.masic-promo h3{font-size:clamp(32px,4vw,55px)}
.masic-promo p{line-height:1.7;color:rgba(40,38,34,.7)}
.masic-instagram{display:grid;grid-template-columns:.9fr 1.1fr;min-height:680px}
.masic-instagram__photo{min-height:520px;background:center/cover no-repeat}
.masic-instagram__copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(42px,8vw,120px);background:#d8d0bf}
.masic-instagram__copy h2{font-size:clamp(42px,5.2vw,78px)}
@media(max-width:900px){
 .masic-shell{width:min(100% - 28px,1320px)}
 .masic-hero{min-height:820px}
 .masic-hero__content{padding-top:140px}
 .masic-hero__meta{flex-direction:column;gap:8px}
 .masic-copy,.masic-media{grid-column:1/-1}
 .masic-media{margin-top:28px}
 .masic-cards{grid-template-columns:1fr}
 .masic-card{min-height:440px}
 .masic-menu{grid-template-columns:1fr}
 .masic-gallery{grid-template-columns:1fr 1fr}
 .masic-gallery img{height:460px}
 .masic-gallery img:nth-child(2){height:460px;margin-top:0}
 .masic-gallery img:nth-child(3){grid-column:1/-1;width:70%;height:420px;margin:0 auto}
 .masic-contact,.masic-instagram{grid-template-columns:1fr}
}
@media(max-width:600px){
 .masic-title{font-size:45px}
 .masic-lead{font-size:17px}
 .masic-actions{flex-direction:column}
 .masic-btn{width:100%}
 .masic-section{padding:72px 0}
 .masic-heading{display:block}
 .masic-heading p{margin-top:20px}
 .masic-facts{grid-template-columns:1fr}
 .masic-gallery{display:block}
 .masic-gallery img,.masic-gallery img:nth-child(2),.masic-gallery img:nth-child(3){width:100%;height:420px;margin:12px 0}
 .masic-instagram__photo{min-height:480px}
}
